<#
.SYNOPSIS
    Feature 245: fixture configurations of old programs (dot-source after ci245_lib.ps1).
    Every fixture lives under HKCU\Software\Tandem Commander Test 245\<product name>.
#>

# password blobs generated by the Debug build's seam ([fixture] gen=1): S = scrambled,
# E = AES under 'master', V = the verifier of 'master'
function Get-Blobs([string]$Exe, [string]$WorkDir, [string]$Plain, [string]$Master) {
    $r = Invoke-TC $Exe "[fixture]`r`ngen=1`r`nplain=$Plain`r`nmaster=$Master`r`n" $WorkDir "blob_$($Plain.Length)" 60 'Software\Tandem Commander Test 245 Empty'
    if ($null -eq $r.Fixture) { throw "blob generation failed: $($r | Out-String)" }
    $h = @{}
    foreach ($l in ($r.Fixture -split "`r`n")) { if ($l.Length -gt 2) { $h[$l.Substring(0, 1)] = HexToBytes $l.Substring(2) } }
    return $h
}

# a typical Altap Salamander 4.0 configuration
#   $Version   the configuration version (103 = 4.0)
#   $Blobs     @{S; E; V} or $null (no passwords)
#   $UseMaster the source uses a master password (bookmark 2 then carries the E blob)
function New-AltapFixture([string]$Name = 'Altap Salamander 4.0', [int]$Version = 103, $Blobs = $null, [bool]$UseMaster = $false) {
    $root = Join-Path $script:FixPS $Name
    if (Test-Path -LiteralPath $root) { Remove-Item -LiteralPath $root -Recurse -Force }
    $spec = @{
        'Version'                                           = @{ 'Configuration' = $Version }
        'Configuration'                                     = @{ 'Single Click' = 1; 'Sort Dirs By Ext' = 1; 'Theme Mode' = 1; 'Panel Tabs' = 0; 'Language' = 'czech.slg'; 'Thumbnail Size' = 5000; 'Use Recycle Bin' = 2; 'Use Recycle Bin For' = '*.doc;*.tmp'; 'Compare Ignore Files' = 1 }
        'Configuration\Confirmation'                        = @{ 'File Overwrite' = 0; 'Close Find' = 0 }
        'Configuration\ChangeDir History'                   = @{ '1' = 'C:\Old\History'; '2' = 'ftp://joe:secret@host/dir' }
        'Hot Paths\1'                                       = @{ 'Name' = 'Projects'; 'Path' = 'C:\Projects'; 'Visible' = 1 }
        'Hot Paths\2'                                       = @{ 'Name' = 'C:\Windows'; 'Path' = 'C:\Windows'; 'Visible' = 1 }
        'Hot Paths\3'                                       = @{ 'Name' = 'Salamander'; 'Path' = '$(SalDir)\plugins'; 'Visible' = 0 }
        'Hot Paths\12'                                      = @{ 'Name' = ([string][char]0x010D + 'esky'); 'Path' = ('D:\' + [char]0x017D + 'lu' + [char]0x0165 + 'ou' + [char]0x010D + 'k'); 'Visible' = 1 }
        'User Menu\1'                                       = @{ 'Item Name' = '&Notepad'; 'Command' = 'notepad.exe'; 'Arguments' = '"$(FullName)"'; 'Initial Directory' = '$(Drive)$(Path)'; 'Execute Through Shell' = 0; 'Close Shell Window' = 1; 'Type' = 0 }
        'User Menu\2'                                       = @{ 'Item Name' = 'Old tool'; 'Command' = 'C:\Program Files\Altap Salamander\tool.exe'; 'Execute Through Shell' = 0; 'Close Shell Window' = 1; 'Type' = 0 }
        'Viewers\1'                                         = @{ 'Masks' = '*.log'; 'Type' = 0; 'Command' = 'notepad.exe' }
        'Viewers\2'                                         = @{ 'Masks' = '*.htm;*.html'; 'Type' = -1 }
        'Viewers\3'                                         = @{ 'Masks' = '*.jpg'; 'Type' = -3 }
        'Editors\1'                                         = @{ 'Masks' = '*.ini'; 'Command' = 'notepad.exe' }
        'Plugins\1'                                         = @{ 'DLL' = 'ieviewer\ieviewer.spl'; 'Name' = 'Internet Explorer Viewer'; 'Configuration Key' = 'IEVIEWER' }
        'Plugins\2'                                         = @{ 'DLL' = 'ftp\ftp.spl'; 'Name' = 'FTP Client'; 'Configuration Key' = 'FTP' }
        'Plugins\2\Menu\1'                                  = @{ 'Name' = 'Connect to FTP Server'; 'ID' = 1; 'State' = 0; 'HotKey' = (0x10000 -bor 0x0646) }
        'Plugins\3'                                         = @{ 'DLL' = 'C:\Program Files\Altap Salamander\plugins\pictview\pictview.spl'; 'Name' = 'PictView'; 'Configuration Key' = 'PictView' }
        'Plugins\4'                                         = @{ 'DLL' = 'renamer\renamer.spl'; 'Name' = 'Renamer'; 'Configuration Key' = 'Renamer' }
        'Plugins Configuration\FTP'                         = @{ 'Version' = 37 }
        'Plugins Configuration\FTP\Bookmarks\1'             = @{ 'Name' = 'Altap'; 'Address' = 'ftp.altap.cz'; 'Initial Path' = '/pub'; 'Anonymous' = 1 }
        'Plugins Configuration\FTP\Proxy Servers\1'         = @{ 'Unique ID' = 7; 'Name' = 'Office proxy'; 'Type' = 3; 'Host' = 'proxy.example'; 'Port' = 8080; 'User' = '' }
        'Plugins Configuration\IEVIEWER'                    = @{ 'Version' = 1 }
        'Plugins Configuration\Renamer'                     = @{ 'Last Used Options' = 'x' }
        'Password Manager'                                  = @{ 'Use Master Password' = $(if ($UseMaster) { 1 } else { 0 }) }
    }
    $bm2 = @{ 'Name' = 'Work'; 'Address' = 'ftp.work.example'; 'User' = 'joe'; 'Anonymous' = 0; 'Proxy Server UID' = 7; 'Port' = 21 }
    if ($null -ne $Blobs) {
        if ($UseMaster) { $bm2['PasswordE'] = $Blobs['E'] } else { $bm2['PasswordS'] = $Blobs['S'] }
        $bm2['Save Password'] = 1
    }
    $spec['Plugins Configuration\FTP\Bookmarks\2'] = $bm2
    if ($UseMaster -and $null -ne $Blobs) { $spec['Password Manager']['Master Password Verifier'] = $Blobs['V'] }
    Set-RegTree $root $spec
    return $root
}
